from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        S = [0] * (n + 1)
        for i in range(n):
            S[i + 1] = S[i] + nums[i]

        NEG = float('-inf')
        prev = [0] * (n + 1)  # j = 0: zero subarrays => sum 0 for any i

        for j in range(1, k + 1):
            curr = [NEG] * (n + 1)
            best = NEG  # max over valid p <= i - m of (prev[p] - S[p])
            for i in range(j * m, n + 1):
                p = i - m
                if prev[p] != NEG:
                    val = prev[p] - S[p]
                    if val > best:
                        best = val
                option1 = curr[i - 1]
                option2 = S[i] + best if best != NEG else NEG
                curr[i] = option1 if option1 > option2 else option2
            prev = curr

        return prev[n]
